type AreaSeries = {
  readonly id: string;
  readonly label: string;
  readonly values: readonly (number | null)[];
  readonly color?: string;
  readonly opacity?: number;
  /** Native FillTarget입니다. 숫자 기준선은 { value: number }로 지정합니다. */
  readonly baseline?: FillTarget;
  /** 완성된 fill 색상입니다. 명시한 alpha를 유지하며 opacity를 다시 적용하지 않습니다. */
  readonly above?: string;
  /** 완성된 fill 색상입니다. 명시한 alpha를 유지하며 opacity를 다시 적용하지 않습니다. */
  readonly below?: string;
  readonly hidden?: boolean;
  readonly stack?: string;
  /** tension, stepped, segment와 native fill 등 개별 dataset 설정입니다. */
  readonly datasetOptions?: Omit<ChartDataset<'line', (number | null)[]>, 'data' | 'label'>;
};

type AxisLabelGroup = {
  readonly id: string;
  readonly start: number;
  readonly end: number;
  readonly label: string | readonly string[];
};

type BoxPlotData = Omit<ChartData<'boxPlot', BoxPlotDatum[], string>, 'datasets'> & {
  readonly datasets: (ChartDataset<'boxPlot', BoxPlotDatum[]> & {
    readonly id: string;
  })[];
};

type BoxPlotDatasetOptions<TType extends 'boxPlot' = 'boxPlot'> = BoxStatisticsOptions & ScriptableAndArrayOptions<BoxPlotElementOptions, ScriptableContext<TType>> & {
  readonly id: string;
};

type BoxPlotDatum = {
  readonly id: string;
  readonly label?: string;
} & ({
  readonly kind: 'observations';
  readonly values: readonly (number | null)[];
} | {
  readonly kind: 'statistics';
  readonly statistics: BoxPlotStatistics;
});

interface BoxPlotElementOptions {
  readonly backgroundColor: string;
  readonly borderColor: string;
  readonly borderWidth: number;
  readonly medianColor: string;
  readonly medianWidth: number;
  readonly whiskerColor: string;
  readonly whiskerWidth: number;
  readonly outlierColor: string;
  readonly outlierRadius: number;
  readonly showBox: boolean;
  readonly showMedian: boolean;
  readonly showWhiskers: boolean;
  readonly showOutliers: boolean;
  readonly widthRatio: number;
}

interface BoxPlotStatistics {
  readonly min: number;
  readonly q1: number;
  readonly median: number;
  readonly q3: number;
  readonly max: number;
  readonly low: number;
  readonly high: number;
  readonly outliers: readonly number[];
}

interface BoxPlotTooltipContext {
  readonly raw: BoxPlotDatum;
  readonly statistics: BoxPlotStatistics | null;
  readonly outlier: {
    readonly index: number;
    readonly value: number;
  } | null;
}

{
    readonly index: number;
    readonly value: number;
  } | null

interface BoxPlotTooltipLabels {
  readonly min: string;
  readonly q1: string;
  readonly median: string;
  readonly q3: string;
  readonly max: string;
  readonly whiskers: string;
  readonly outliers: string;
}

interface BoxStatisticsOptions {
  readonly quantile?: 'r7' | 'tukey' | ((sorted: readonly number[], fraction: number) => number);
  readonly whiskers?: 'iqr' | 'minmax';
  readonly whiskerMultiplier?: number;
}

CHART_SERIES_INDICATOR_VARIANT: {
  readonly bullet: 'bullet';
  readonly dashedLine: 'dashedLine';
  readonly dashedLineWithBullet: 'dashedLineWithBullet';
  readonly line: 'line';
  readonly lineWithBullet: 'lineWithBullet';
  readonly square: 'square';
}

type ChartAxisDomain = {
  end: number;
  start: number;
};

type ChartAxisLabelMarkerOptions = {
  color?: string;
  length?: number;
  lineWidth?: number;
  scaleId?: string;
};

type ChartBarSegmentLabelOptions = {
  readonly palette: ChartPalette;
  /** 기본값 true. 숫자가 아닌 값, 0, NaN/Infinity와 line dataset은 숨긴다. */
  readonly enabled?: boolean;
  readonly formatter?: ChartBarSegmentLabelFormatter;
  /** family는 palette, 나머지는 chart.options.font와 Chart.js 기본값을 따른다. */
  readonly font?: {
    readonly family?: string;
    readonly size?: number;
    readonly style?: 'normal' | 'italic' | 'oblique';
    readonly weight?: 'normal' | 'bold' | 'bolder' | 'lighter' | number;
    readonly lineHeight?: string | number;
  };
  /** 기본값 4. 숫자 또는 방향별 padding을 사용한다. */
  readonly padding?: number | {
    readonly top?: number;
    readonly right?: number;
    readonly bottom?: number;
    readonly left?: number;
  };
};

{
    readonly family?: string;
    readonly size?: number;
    readonly style?: 'normal' | 'italic' | 'oblique';
    readonly weight?: 'normal' | 'bold' | 'bolder' | 'lighter' | number;
