type ChartCartesianData = ChartData<ChartType, number[], ChartCategoryValue> & {
  datasets: ChartCartesianDataset[];
};

type ChartCartesianDataset = ChartDataset<ChartType, number[]> & {
  id?: string | number;
};

type ChartColorsOptions = {
  readonly mode: 'light' | 'dark';
  readonly surface: string;
  /** 기본값 3. 불가능한 대비는 가장 대비가 높은 같은 계열 색상을 반환한다. */
  readonly minContrast?: number;
};

type ChartDragZoomOptions = {
  backgroundColor?: string;
  borderColor?: string;
  borderWidth?: number;
  drag?: ChartZoomDragTriggerOptions;
  drawTime?: 'afterDatasetsDraw' | 'afterDraw' | 'beforeDatasetsDraw' | 'beforeDraw';
  enabled?: boolean;
  limits?: Record<string, ChartZoomPluginScaleLimit>;
  minRange?: number;
  mode?: ChartZoomPluginMode;
  modifierKey?: ChartZoomPluginModifierKey;
  pinch?: ChartZoomPinchOptions;
  threshold?: number;
  wheel?: ChartZoomWheelOptions;
};

type ChartErrorOverlayOptions = {
  /** 오류 메시지. 기본값: “데이터를 불러오지 못했습니다.” (i18n 적용) */
  readonly message?: ReactNode;
  /** 미지정 시 재시도 버튼을 표시하지 않는다. */
  readonly onRetry?: () => void | Promise<unknown>;
  /** 재시도 버튼 문구. 기본값: “다시 시도” (i18n 적용) */
  readonly retryLabel?: string;
};

type ChartExternalTooltipContext = {
  chart: Chart;
  tooltip: TooltipModel<ChartType>;
};

