type ChartFrameExportHandle = {
  /** Chart와 legend를 PNG raw base64 문자열로 반환 */
  toPngBase64: (options?: ChartFramePngExportOptions) => string;
  /** Chart와 legend를 PNG Blob으로 반환 */
  toPngBlob: (options?: ChartFramePngExportOptions) => Promise<Blob>;
  /** Chart와 legend를 PNG data URL로 반환 */
  toPngDataUrl: (options?: ChartFramePngExportOptions) => string;
  /** Chart와 legend를 PNG 파일로 다운로드 */
  downloadPng: (fileName?: string, options?: ChartFramePngExportOptions) => Promise<void>;
};

type ChartFrameExternalTooltipOptions = {
  /** CSS pixel 기준 최대 높이 */
  maxHeight?: number;
  /** viewport 경계와 tooltip 사이의 최소 간격 */
  viewportPadding?: number;
};

type ChartFramePngExportOptions = {
  backgroundColor?: false | string;
  fontFamily?: string;
  legend?: false | ChartLegendOptions;
  pixelRatio?: number;
};

type ChartFrameProps<TType extends ChartType = ChartType, TData = DefaultDataPoint<TType>, TLabel = unknown> = ChartFrameBaseProps<TType, TData, TLabel> & {
  /** OWP theme·HTML tooltip·interaction 기본값. 미지정 시 기존 동작을 유지한다. */
  preset?: 'owp';
  /** 지정하면 범례는 변경 요청만 보낸다. dataset.hidden은 별도 표시 gate다. */
  visibility?: ChartVisibility;
  onVisibilityChange?: (visibility: ChartVisibility) => void;
  /** canvas 경계를 벗어날 수 있는 HTML external tooltip */
  externalTooltip?: boolean | ChartFrameExternalTooltipOptions;
  /** PNG 다운로드 파일명 */
  exportFileName?: string;
  /** Chart canvas와 custom legend만 PNG로 내보내는 imperative handle ref */
  exportRef?: Ref<ChartFrameExportHandle>;
  interactionLayer?: false | ChartInteractionLayerOptions;
  legend?: false | ChartLegendOptions;
  /** 동일 group의 chart pointer와 zoom 동기화 */
  linkedInteraction?: false | ChartLinkedInteractionOptions;
  /** Chart plot 영역 loading overlay 표시 여부 */
  loading?: boolean;
  /** 빈 데이터 표시는 호출자가 제어한다. 기본값 false이며 null·0·숨김 상태로 자동 판정하지 않는다. */
  noData?: boolean;
  /** noData=true일 때 표시할 문구. 기본값: “조회 결과가 없습니다.” (i18n 적용) */
  noDataMessage?: string;
  /** 오류 안내와 재시도 action. 우선순위는 loading → errorOverlay → noData다. */
  errorOverlay?: false | ChartErrorOverlayOptions;
  /** Chart 상단 오른쪽 PNG 다운로드 버튼 표시 여부 */
  showExportButton?: boolean;
  /** Chart.js title plugin에 표시할 chart title */
  title?: string;
  /** x축 label 기준점에 표시하는 짧은 marker */
  xAxisLabelMarker?: false | ChartAxisLabelMarkerOptions;
  zoomSlider?: false | ChartZoomSliderOptions;
};

