type ChartInteractionLayerOptions = {
  disabled?: boolean;
  dragZoom?: false | ChartDragZoomOptions;
  hoverAreaColor?: string;
  referenceAxis?: ChartReferenceAxis;
  referenceLineColor?: string;
  referenceScaleId?: string;
  showHoverArea?: boolean;
  showReferenceLine?: boolean;
};

type ChartItemIdentity = {
  readonly id: string;
  readonly label: string;
  readonly color?: string;
};

type ChartLegendItem = {
  id?: string;
  dataIndex?: number;
  color?: string;
  datasetIndex: number;
  hidden: boolean;
  label: unknown;
  line?: boolean;
  pointRadius?: unknown;
  stroke?: string;
  strokeDasharray?: string;
  type?: string;
};

type ChartLegendOptions = {
  /** 기본 160ms. false/0은 즉시 반영하며 음수·NaN·Infinity는 RangeError다. */
  animation?: false | {
    duration?: number;
  };
  align?: 'left' | 'center' | 'right';
  position?: 'top' | 'bottom';
  /** auto는 단일 원형의 항목, 그 외 차트의 series를 표시한다. */
  mode?: 'auto' | 'series' | 'items' | 'both';
  title?: string;
  formatter?: (label: string, item: ChartLegendItem) => string;
  onClick?: (item: ChartLegendItem) => void;
  onHover?: (item: ChartLegendItem) => void;
};

type ChartLegendProps<TType extends ChartType = ChartType, TData = DefaultDataPoint<TType>, TLabel = unknown> = Omit<ChartLegendOptions, 'animation'> & {
  chart: Chart<TType, TData, TLabel> | null;
  data: ChartData<TType, TData, TLabel>;
  type: TType;
};

type ChartLinkedInteractionOptions = {
  enabled?: boolean;
  group?: number | string;
  scaleId?: string;
  suppressSyncedTooltip?: boolean;
  /** Pointer 매칭 기준. label 모드의 category zoom은 공통 label 범위를 적용하며, 공통 label이 없으면 유지 */
  syncBy?: ChartLinkedInteractionSyncMode;
  syncCrosshair?: boolean;
  syncTooltip?: boolean;
  /** Zoom·slider 범위·reset 동기화 여부. 기본값 true */
  syncZoom?: boolean;
};

type ChartPalette = {
  readonly colors: readonly string[];
  readonly fontFamily: string;
  readonly contrastText: (background: string) => string;
  readonly ink: string;
  readonly muted: string;
  readonly surface: string;
  readonly line: string;
  readonly danger: string;
  readonly success: string;
  readonly warning: string;
};

type ChartPaletteOptions = {
  readonly surface?: string;
  /** 명시한 배열은 대비 보정 없이 그대로 사용한다. 빈 배열도 유지한다. */
  readonly colors?: readonly string[];
  readonly minContrast?: number;
};

type ChartScaleOptions = Record<string, unknown> & {
  grid?: Record<string, unknown>;
  ticks?: Record<string, unknown>;
};

type ChartScrollSnapshot = {
  element: HTMLElement;
  left: number;
  top: number;
};

type ChartSeriesConfig<T extends ChartDataRecord = ChartDataRecord> = {
  /** label·dataKey와 독립적인 ID. datasetOptions.id보다 우선하며 datasetIdKey="id"와 사용한다. */
  id?: string;
  backgroundColor?: string;
  borderColor?: string;
  color?: string;
  dataKey: keyof T & string;
  datasetOptions?: ChartDatasetOptions;
  hidden?: boolean;
  label?: string;
  order?: number;
  stack?: string;
  type: ChartDatasetType;
  yAxisId?: ChartAxisId;
};

type ChartSeriesIndicatorEntry = {
  color?: string;
  dot?: unknown;
  indicatorVariant?: ChartSeriesIndicatorVariant;
  line?: boolean;
  payload?: unknown;
  stroke?: string;
  strokeDasharray?: ChartNumericValue;
  type?: string;
};

type ChartTimeAdapterOptions = {
  readonly zone?: string;
  readonly locale?: string;
  readonly setZone?: boolean;
  readonly numberingSystem?: string;
  readonly outputCalendar?: string;
};

type ChartTimePoint<TX extends ChartTimeValue = number> = {
  readonly x: TX;
  readonly y: number | null;
};

type ChartTrendlineLabelOptions = {
  color?: ChartTrendlineColor;
  display?: boolean;
  displayValue?: boolean;
  font?: {
    family?: string;
    size?: number;
  };
  offset?: number;
  percentage?: boolean;
  text?: string;
};

type ChartTrendlineLegendOptions = {
  color?: ChartTrendlineColor;
  display?: boolean;
  fillStyle?: ChartTrendlineColor;
  lineCap?: CanvasLineCap;
  lineDash?: number[];
  lineWidth?: number;
  strokeStyle?: ChartTrendlineColor;
  text?: string;
  width?: number;
};

type ChartTrendlineOptions = {
  colorMax?: ChartTrendlineColor;
  colorMin?: ChartTrendlineColor;
  fillColor?: false | ChartTrendlineColor;
  label?: ChartTrendlineLabelOptions;
  legend?: ChartTrendlineLegendOptions;
  lineStyle?: ChartTrendlineLineStyle;
  projection?: boolean;
  trendoffset?: number;
  width?: number;
  xAxisKey?: string;
  yAxisKey?: string;
};

type ChartZoomDragTriggerOptions = boolean | {
  backgroundColor?: string;
  borderColor?: string;
  borderWidth?: number;
  drawTime?: 'afterDatasetsDraw' | 'afterDraw' | 'beforeDatasetsDraw' | 'beforeDraw';
  enabled?: boolean;
  maintainAspectRatio?: boolean;
  modifierKey?: ChartZoomPluginModifierKey;
  threshold?: number;
};

type ChartZoomPluginScaleLimit = {
  max?: number | 'original';
  min?: number | 'original';
  minRange?: number;
};

type ChartZoomResetButtonProps = {
  /** 숨김 전환 시 포커스를 되돌릴 차트 프레임 element ref */
  focusTargetRef?: RefObject<HTMLElement | null>;
  onClick: () => void;
  rightOffset?: number;
  topOffset?: number;
  visible: boolean;
};

type ChartZoomSliderAxisOptions = {
  /** 핸들 aria-label에 사용할 축 이름. 생략 시 scale title 또는 번역된 기본 축 이름을 사용한다. */
  ariaLabel?: string;
  end?: number;
  max?: number;
  min?: number;
  position?: ChartZoomSliderPosition;
  scaleId?: string;
  start?: number;
  step?: number;
  /** 핸들 현재 값의 aria-valuetext formatter */
  valueTextFormatter?: (value: number, context: ChartZoomSliderValueTextContext) => string;
};

type ChartZoomSliderChart = ChartZoomSliderChartSource & {
  update: (mode?: UpdateMode) => void;
};

type ChartZoomSliderChartSource = {
  options?: unknown;
  scales?: Record<string, ChartZoomSliderScale>;
  width?: number;
};

type ChartZoomSliderOptions = {
  x?: boolean | ChartZoomSliderAxisOptions;
  y?: false | ChartZoomSliderAxisOptions;
  y1?: false | ChartZoomSliderAxisOptions;
  y2?: false | ChartZoomSliderAxisOptions;
};

type ChartZoomSliderRange = {
  end: number;
  start: number;
};

type ChartZoomSliderScale = {
  getLabelForValue?: (value: number) => string;
  getLabels?: () => unknown[];
  left?: number;
  max?: unknown;
  min?: unknown;
  options?: unknown;
  right?: number;
  type?: string;
};

type ChartZoomSlidersProps = {
  chart: ChartZoomSliderChart | null;
  chartArea: ChartArea | null;
  data: ChartZoomSliderData;
  onZoomStateChange?: ChartZoomStateChangeHandler;
  placement: 'bottom' | 'plot';
  resetVersion: number;
  side?: Extract<ChartZoomSliderPosition, 'left' | 'right'>;
  syncVersion: number;
  zoomSlider: ChartZoomSliderOptions;
};

type ChartZoomSliderValueTextContext = {
  axis: ChartZoomSliderAxisKey;
  edge: ChartZoomSliderHandleEdge;
  label: unknown;
  scaleId: string;
};

type ChartZoomWheelOptions = boolean | {
  enabled?: boolean;
  modifierKey?: ChartZoomPluginModifierKey;
  speed?: number;
};

type CoreChartProps<TType extends ChartType = ChartType, TData = DefaultDataPoint<TType>, TLabel = unknown> = ChartProps<TType, TData, TLabel> & {
  chartRef?: Ref<Chart<TType, TData, TLabel> | undefined>;
  containerClassName?: string;
  containerStyle?: CSSProperties;
  height?: CSSProperties['height'];
};

