  /** 닫기 확인 UI를 Dialog 옆에 render한다. */
  readonly confirmation?: ReactNode;
  /** 취소 버튼의 mousedown에서 편집 중인 element의 focus를 유지한다. */
  readonly preserveCancelFocus?: boolean;
  /** 사용자 transition onEntered 다음에 호출한다. */
  readonly onEntered?: () => void;
  /** 외부 manager의 stack 순서. 공통 local stack 순서와 큰 값을 사용한다. */
  readonly stackIndex?: number;
}

interface OwpDialogsProviderProps extends DialogProviderProps {
  /** 값이 변경되면 열린 dialog를 위에서부터 닫는다. */
  readonly closeAllSignal?: number;
  /** 외부 알림 backend. 생략하면 상위 feedback 또는 MUI Snackbar를 사용한다. */
  readonly notify?: OwpFeedback['notify'];
}

interface OwpDiscardGuard {
  /**
   * dirty가 아니면 바로 실행하고, dirty면 확인 후 한 번 실행.
   * 실행 완료 시 true, 취소·중복 요청·실행 전 unmount 시 false. getter나 callback에서 오류가 나면 Promise가 reject된다.
   * true는 action 실행 완료만 뜻하며 dirty나 저장 기준을 바꾸지 않음.
   * 실행 중 추가 요청은 false. 이미 실행 중인 callback은 unmount로 중단되지 않음.
   * @param options 이 동작의 dirty override와 확인 문구
   */
  requestDiscard: (action: () => void | Promise<void>, options?: OwpDiscardRequestOptions) => Promise<boolean>;
  /** 확인 UI. 직접 한 번 render하거나 OwpDialog.discardGuard에 연결 */
  readonly confirmation: ReactNode;
}

interface OwpDiscardRequestOptions {
  /** action별 dirty override (default: guard dirty) */
  isDirty?: OwpDirtySource;
  /** 기본값 discard. 문구는 Components i18n에서 관리 */
  intent?: OwpDiscardIntent;
}

declare class OwpErrorBoundary extends Component<OwpErrorBoundaryProps, OwpErrorBoundaryState> {
  constructor(props: OwpErrorBoundaryProps);
  static getDerivedStateFromError(error: unknown): OwpErrorBoundaryState;
  componentDidCatch(error: unknown, errorInfo: ErrorInfo): void;
  render(): string | number | bigint | boolean | import("react").JSX.Element | Iterable<import("react").ReactNode> | Promise<string | number | bigint | boolean | Iterable<import("react").ReactNode> | import("react").ReactElement<unknown, string | import("react").JSXElementConstructor<any>> | import("react").ReactPortal>;
}

interface OwpErrorBoundaryProps {
  readonly children?: ReactNode;
  /** 동기적으로 true를 반환하면 errorInfo 갱신과 onError 호출을 생략한다. fallback은 유지한다. */
  readonly onErrorRecovery?: (error: unknown, info: ErrorInfo) => boolean;
  /** 복구되지 않은 오류를 errorInfo와 함께 state에 전달한 직후 호출한다. */
  readonly onError?: (error: unknown, info: ErrorInfo) => void;
}

type OwpErrorBoundaryState = {
  readonly hasError: boolean;
  readonly error: unknown;
  readonly errorInfo: ErrorInfo | null;
};

interface OwpFeedback {
