   */
  commitEditing: () => boolean;
  /**
   * 편집 중이면 실패. 모든 operation을 staging한 뒤 반영, onChangesChange 한 번 호출.
   * 성공 이후 onCellValueCommit을 operation 순서로 전달. setter/validator 예외는 callback-error.
   * 성공 알림 callback 예외는 호출부로 전파하며 이미 반영한 model을 rollback하지 않음.
   */
  applyTransaction: (operations: readonly OwpDataGridTransactionOperation<T>[]) => OwpDataGridCommandResult;
  /**
   * 저장된 전체 row로 baseline 갱신, 요청 이후 수정 보존. 편집 중이면 실패.
   * 전달된 row만 반영하고 onChangesChange 한 번 호출. 서버 응답 순서/버전 검사는 호출부 책임.
   */
  applyServerRows: (options: OwpDataGridServerRowsOptions<T>) => OwpDataGridCommandResult;
  /**
   * rowIds에 포함된 row의 현재 값과 순서를 새 baseline으로 확정. default: loaded row 전체, []: no-op.
   * 삭제 승인은 loaded subtree 전체 ID 필요. 요청 중 추가 수정이 가능하면 applyServerRows 사용.
   * 편집 중이면 실패. HTTP 저장은 호출부 책임.
   */
  acceptChanges: (rowIds?: readonly OwpDataGridRowId[]) => OwpDataGridCommandResult;
  /**
   * 전달된 신규행만 취소. 삭제 상태인 신규 row도 가능하며 다른 미저장 변경은 보존.
   * 기존행/없는 ID 포함 시 invalid-target, loaded descendant ID 누락 시 incomplete-subtree.
   * 편집 중이면 editing-active. 전체 성공/실패하며 []는 no-op, 중복 ID는 한 번 처리.
   * span 그룹으로 자동 확장하지 않음. 취소한 행은 undeleteRows/resetChanges로 복원되지 않음.
   */
  discardAddedRows: (rowIds: readonly OwpDataGridRowId[]) => OwpDataGridCommandResult;
  /** 삭제 상태인 row를 제외한 현재 active row를 tree preorder의 flat 배열로 반환 */
  getRows: () => T[];
  /** filter/sort/expansion과 삭제된 row 표시 설정을 적용한 flat row 반환 */
  getVisibleRows: () => T[];
  /** ID로 현재 active row를 조회 */
  getRow: (rowId: OwpDataGridRowId) => T | undefined;
  /** 현재 선택된 active row를 반환 */
  getSelectedRows: () => T[];
  /** 현재 working/display 상태를 Excel 내보내기용 snapshot으로 반환 */
  getExcelSnapshot: (options?: OwpDataGridExcelSnapshotOptions) => OwpDataGridExcelSnapshot<T>;
  /** 현재 표시 컬럼과 상세 패널의 Excel 누락 안내. 행을 순회하지 않는다. */
  getExcelExportWarnings?: () => {
    excludedColumnLabels: string[];
    customCellColumnLabels: string[];
    hasDetailPanel: boolean;
  };
  /** 대용량 Excel을 순차 batch로 읽는다. 기존 동기 snapshot API는 유지한다. */
  createExcelExportSession?: (options: OwpDataGridExcelExportSessionOptions) => Promise<OwpDataGridExcelExportSession<T>>;
  /** Cell working value를 변경 */
  setCellValue: (rowId: OwpDataGridRowId, columnId: string, value: unknown) => boolean;
  /** Working topology에 row 또는 nested subtree를 추가. 기본 위치는 root-last */
  addRow: (row: T, placement?: OwpDataGridRowPlacement) => boolean;
  /** Row와 loaded subtree를 working topology에서 soft-delete하고 영향받은 ID를 반환 */
  deleteRows: (rowIds: readonly OwpDataGridRowId[]) => OwpDataGridRowId[];
  /** 삭제된 row subtree를 삭제 직전 위치로 복원하고 영향받은 ID를 반환 */
  undeleteRows: (rowIds: readonly OwpDataGridRowId[]) => OwpDataGridRowId[];
  /** Row subtree를 working topology 안에서 이동 */
  moveRow: (rowId: OwpDataGridRowId, placement: OwpDataGridRowPlacement) => boolean;
  /** 비연속 row subtree를 현재 topology 순서의 한 block으로 atomic 이동 */
  moveRows: (rowIds: readonly OwpDataGridRowId[], placement: OwpDataGridRowPlacement) => boolean;
  /** Row의 lazy direct children을 최초 로딩 */
  loadChildren: (rowId: OwpDataGridRowId) => Promise<boolean>;
  /** 변경이 없는 기존 lazy subtree를 교체 로딩하거나 실패 요청을 재시도 */
  reloadChildren: (rowId: OwpDataGridRowId) => Promise<boolean>;
  /** Row의 lazy children 요청 상태 조회 */
  getChildrenLoadState: (rowId: OwpDataGridRowId) => OwpDataGridChildrenLoadState | undefined;
  /** Row를 expand */
  expandRow: (rowId: OwpDataGridRowId) => void;
  /** Row를 collapse */
  collapseRow: (rowId: OwpDataGridRowId) => void;
  /** 현재 active expandable row를 모두 expand */
  expandAll: () => void;
  /** 모든 row를 collapse */
  collapseAll: () => void;
  /** 현재 working-copy change를 반환 */
  getChanges: () => OwpDataGridChange<T>[];
  /**
   * Working-copy의 추가·수정·삭제·이동 또는 현재 cell의 미확정 입력 변경 여부.
   * 편집 확정·검증·callback 호출 없이 조회. 비교 기준은 마지막 승인 baseline.
   */
  hasUnsavedChanges: () => boolean;
  /** Working-copy와 validation state를 마지막 승인 baseline으로 reset. 승인 전에는 초기 rows 기준 */
  resetChanges: () => void;
  /** 현재 active row에 저장된 오류를 cell당 하나씩 반환. 같은 cell은 external 오류가 우선 */
  getCellErrors: () => OwpDataGridValidationError<T>[];
  /** 외부 cell 오류를 추가하거나 교체. 빈 message는 해당 오류를 제거 */
  setCellError: (rowId: OwpDataGridRowId, columnId: string, message: ReactNode) => boolean;
  /** 외부 cell 오류 전체 교체. 잘못된 row/column이 있으면 false를 반환하고 기존 상태 유지 */
  setCellErrors: (errors: readonly OwpDataGridCellError[]) => boolean;
  /** 지정한 외부 cell 오류를 제거 */
  clearCellError: (rowId: OwpDataGridRowId, columnId: string) => boolean;
  /** 외부 cell 오류 전체를 제거 */
  clearCellErrors: () => void;
  /** 현재 active row 전체 또는 지정 범위를 validate. external 오류 포함 기본값 true */
  validate: (options?: OwpDataGridValidationOptions) => OwpDataGridValidationResult<T>;
