  scrollToRow: (rowId: OwpDataGridRowId, align?: 'auto' | 'start' | 'center' | 'end') => boolean;
  /** Visible cell을 viewport로 이동하고 focus */
  focusCell: (rowId: OwpDataGridRowId, columnId: string) => boolean;
